class Order private constructor(private val cartId: CartId, private val buyerId: BuyerId) {
    private val _lines = mutableListOf<OrderLine>()
    val lines: List<OrderLine> get() = _lines          // read-only view, not a getter pair
    val isCancellable: Boolean get() = _status == OrderStatus.DRAFT

    fun addLine(sku: Sku, quantity: Quantity) { _lines += OrderLine(sku, quantity) }

    companion object { fun forCart(cartId: CartId, buyerId: BuyerId) = Order(cartId, buyerId) }
}
